import { readdirSync, readFileSync } from "node:fs";
import { defineConfig } from "tsup";

// One entry per arsenal domain (src/domains/<name>.ts, generated by scripts/arsenal.mjs): nuikit-core/<name>.
const domains = Object.fromEntries(readdirSync(new URL("./src/domains", import.meta.url)).map((f) => [f.replace(/\.ts$/, ""), `src/domains/${f}`]));
const { version } = JSON.parse(readFileSync(new URL("./package.json", import.meta.url), "utf8")) as { version: string };

export default defineConfig([
  {
    entry: {
      ...domains,
      index: "src/index.ts",
      react: "src/react.ts",
      // The host (docs/host.md): module side and ui_page boot (nuikit-core/host is the host domain).
      module: "src/module.ts",
      boot: "src/boot.ts",
      // Coverage harness maths (bench/coverage): pure, no imports. Also in nuikit-core/doctor.
      coverage: "src/coverage.ts",
      // React renderers for intents (nuikit-core/intents is the domain).
      "intents-react": "src/intents-react.ts",
    },
    format: ["esm"],
    dts: true,
    clean: false, // two configs share dist/: the build script empties it first
    target: "es2020",
    external: ["react", "react-dom", "react-dom/client", "react/jsx-runtime"],
    define: { __NUIKIT_CORE_VERSION__: JSON.stringify(version) },
  },
  // The theme compiler for the nuikit resource's server script (FXServer's Node runtime).
  {
    entry: { "fxserver-compiler": "src/fxserver.ts" },
    format: ["iife"],
    globalName: "NuikitTheme",
    target: "es2019",
    platform: "neutral",
    minify: false,
    banner: { js: `/* nuikit-core theme compiler (tokens v1) + doctor. MIT, https://github.com/belibathan/nuikit. Generated: do not edit (pnpm sync copies it from packages/core). */` },
    footer: { js: "globalThis.NuikitTheme = NuikitTheme;" },
    outExtension: () => ({ js: ".js" }),
  },
]);
